// The generated file is read by BOTH the drafting skills and the grader, so its
// shape is a contract. grade-brand.mjs splits it on `## N. ` and pulls the
// post_ref out of the first backticked span; if that stops holding, the grader
// silently loses its ground truth and goes back to failing work the client
// approved.

import { test, describe } from "node:test";
import assert from "node:assert/strict";
import { renderCorpus, FILENAME } from "./approved-corpus.mjs";

const POSTS = [
  {
    post_ref: "distribution/linkedin_productized-care.md",
    title: "Somewhere along the way",
    body: "A".repeat(400),
    platform: "linkedin",
    pillar: "positioning",
  },
  {
    post_ref: "script-lab/linkedin_paternalism-belief_draft.md",
    title: "At Clinic we believe",
    body: "B".repeat(400),
    platform: "linkedin",
    pillar: null,
  },
];

describe("approved-examples.md", () => {
  const out = renderCorpus("clinic", POSTS, "2026-08-16");

  test("says it is generated, so nobody edits it by hand", () => {
    assert.match(out, /GENERATED by scripts\/approved-corpus\.mjs/);
    assert.match(out, /Do not edit by hand/);
  });

  test("splits into one section per post, the way the grader parses it", () => {
    const sections = out.split(/\n## \d+\. /).slice(1);
    assert.equal(sections.length, POSTS.length);
  });

  test("each section leads with its post_ref in backticks", () => {
    const sections = out.split(/\n## \d+\. /).slice(1);
    const refs = sections.map((s) => s.match(/`([^`]+)`/)?.[1]);
    assert.deepEqual(refs, POSTS.map((p) => p.post_ref));
  });

  test("carries the post bodies, which are the point of the file", () => {
    assert.ok(out.includes("A".repeat(400)));
    assert.ok(out.includes("B".repeat(400)));
  });

  test("states the count", () => {
    assert.match(out, /2 posts the client approved without changes/);
    assert.match(renderCorpus("clinic", [POSTS[0]], "2026-08-16"), /1 post the client approved/);
  });

  test("is stable across runs with the same input", () => {
    assert.equal(renderCorpus("clinic", POSTS, "2026-08-16"), out);
  });

  test("the filename the grader looks for does not drift", () => {
    assert.equal(FILENAME, "approved-examples.md");
  });
});
